#!/usr/bin/env node
/**
 * Single documentation generator for the command surface.
 *
 * Source of truth: the live command schemas exposed by
 * `dist/index.js <cmd> --schema --json`, plus:
 *   - `dist/registry/commands.js`  → command order, scope, one-line summary
 *   - `skills/<skill>/SKILL.md`    → which skill owns which command
 *   - `package.json`               → version
 *
 * Generated files:
 *   - `docs/commands.md`
 *   - `skills/<skill>/references/commands-quick.md`
 *   - `wiki/commands/index.md`
 *
 * `--check` verifies the generated files are up to date and that every command
 * has a wiki page, without writing anything. It is wired into `npm run verify`.
 *
 * Usage:
 *   node scripts/gen-docs.mjs --write
 *   node scripts/gen-docs.mjs --check
 */
import { execFileSync } from 'node:child_process';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(here, '..');
const distEntry = path.join(repoRoot, 'dist', 'index.js');
const pkg = JSON.parse(fs.readFileSync(path.join(repoRoot, 'package.json'), 'utf8'));
const VERSION = pkg.version;

const args = process.argv.slice(2);
const MODE = args.includes('--write') ? 'write' : args.includes('--check') ? 'check' : undefined;
if (!MODE) {
  console.error('usage: node scripts/gen-docs.mjs --write | --check');
  process.exit(2);
}
if (!fs.existsSync(distEntry)) {
  console.error('gen-docs: dist/index.js missing — run `npm run build` first.');
  process.exit(1);
}

// ─── command specs ──────────────────────────────────────────────────────────
const { COMMAND_SPECS } = await import(pathToFileURL(path.join(repoRoot, 'dist', 'registry', 'commands.js')).href);
const COMMANDS = COMMAND_SPECS.map((spec) => ({
  name: spec.name,
  scope: spec.scope ?? 'sap',
  summary: spec.description ?? '',
}));

function schemaFor(command) {
  const stdout = execFileSync(process.execPath, [distEntry, command, '--schema', '--json'], {
    cwd: repoRoot,
    encoding: 'utf8',
    env: { ...process.env, ABAP_CLI_KEYCHAIN_BACKEND: 'none', NO_COLOR: '1' },
    maxBuffer: 16 * 1024 * 1024,
  });
  const envelope = JSON.parse(stdout);
  if (envelope.status !== 'success' || !envelope.data) {
    throw new Error(`unexpected --schema output for '${command}'`);
  }
  return envelope.data;
}

const schemas = new Map();
for (const cmd of COMMANDS) {
  schemas.set(cmd.name, schemaFor(cmd.name));
}

// ─── markdown helpers ───────────────────────────────────────────────────────
const esc = (value) => String(value ?? '').replace(/\|/g, '\\|').replace(/\n+/g, ' ').trim();
const code = (value) => '`' + String(value).replace(/`/g, '\\`') + '`';

function table(headers, rows) {
  if (rows.length === 0) return '';
  const head = `| ${headers.join(' | ')} |\n| ${headers.map(() => '---').join(' | ')} |`;
  return `${head}\n${rows.map((row) => `| ${row.join(' | ')} |`).join('\n')}`;
}

function renderOptions(options) {
  const rows = (options ?? [])
    .filter((opt) => opt.name !== '--schema')
    .map((opt) => {
      const flags = opt.valuePlaceholder ? `${code(opt.name)} ${code(opt.valuePlaceholder)}` : code(opt.name);
      const required = opt.required ? 'yes' : 'no';
      const def = opt.default === undefined ? '' : code(JSON.stringify(opt.default));
      const values = opt.allowedValues?.length ? opt.allowedValues.join(', ') : '';
      return [flags, required, def, esc(values), esc(opt.description)];
    });
  return table(['Option', 'Required', 'Default', 'Values', 'Description'], rows);
}

function renderArguments(argumentList) {
  const rows = (argumentList ?? []).map((arg) => [
    code(arg.name),
    arg.required ? 'yes' : 'no',
    arg.allowedValues?.length ? arg.allowedValues.join(', ') : '',
    esc(arg.description),
  ]);
  return table(['Argument', 'Required', 'Values', 'Description'], rows);
}

function renderExamples(examples) {
  if (!examples?.length) return '';
  return examples
    .map((example) => `- ${esc(example.description)}${example.command ? `\n\n  \`\`\`bash\n  ${example.command}\n  \`\`\`` : ''}`)
    .join('\n');
}

// ─── docs/commands.md ───────────────────────────────────────────────────────
function renderCommandsDoc() {
  const lines = [];
  lines.push(`# Commands Reference (auto-generated — v${VERSION})`);
  lines.push('');
  lines.push('> Generated by `scripts/gen-docs.mjs` from the live command schemas. Do not edit by hand.');
  lines.push('> Run `npm run build && npm run docs:build` after changing a command; `npm run docs:check` (part of `npm run verify`) fails on drift.');
  lines.push('');
  lines.push('Every command supports `--json` (compact envelope, default for agents) and `--pretty-json`. Success goes to **stdout**, errors to **stderr** with a categorized exit code. See [agent-integration.md](agent-integration.md) for the envelope contract.');
  lines.push('');
  lines.push('## Global options');
  lines.push('');
  lines.push('```');
  lines.push('-V, --version        output the version number');
  lines.push('--json               emit the unified JSON envelope (compact; default for agents)');
  lines.push('--pretty-json        emit the same envelope with 2-space indentation');
  lines.push('-h, --help           display help for a command');
  lines.push('```');
  lines.push('');
  lines.push('## Command index');
  lines.push('');
  lines.push(table(['Command', 'Scope', 'Summary'], COMMANDS.map((cmd) => [code(`abap ${cmd.name}`), cmd.scope, esc(cmd.summary)])));
  lines.push('');

  for (const cmd of COMMANDS) {
    const schema = schemas.get(cmd.name);
    lines.push(`## \`abap ${cmd.name}\``);
    lines.push('');
    lines.push(esc(schema.description ?? cmd.summary));
    lines.push('');
    if (schema.usage) {
      lines.push('```bash');
      lines.push(schema.usage);
      lines.push('```');
      lines.push('');
    }
    if (schema.arguments?.length) {
      lines.push('### Arguments');
      lines.push('');
      lines.push(renderArguments(schema.arguments));
      lines.push('');
    }
    if (schema.options?.length) {
      lines.push('### Options');
      lines.push('');
      lines.push(renderOptions(schema.options));
      lines.push('');
    }
    if (schema.examples?.length) {
      lines.push('### Examples');
      lines.push('');
      lines.push(renderExamples(schema.examples));
      lines.push('');
    }
  }

  // Aggregate error codes from all schemas.
  const codes = new Map();
  for (const schema of schemas.values()) {
    for (const error of schema.errors ?? []) {
      codes.set(error.code, { code: error.code, category: error.category, exitCode: error.exitCode });
    }
  }
  lines.push('## Error codes');
  lines.push('');
  lines.push('Aggregated from the per-command schemas. The authoritative TypeScript source is `src/abap_cli/output/error-codes.ts`; unknown/unmapped failures use `UNKNOWN`.');
  lines.push('');
  lines.push(table(['Code', 'Category', 'Exit'], [...codes.values()].sort((a, b) => a.code.localeCompare(b.code)).map((entry) => [code(entry.code), entry.category ?? '', String(entry.exitCode ?? '')])));
  lines.push('');
  return lines.join('\n');
}

// ─── skills/<skill>/references/commands-quick.md ────────────────────────────
function parseSkillCommands(skillFile) {
  const text = fs.readFileSync(skillFile, 'utf8');
  const frontmatter = /^---\n([\s\S]*?)\n---/.exec(text);
  if (!frontmatter) return [];
  const line = /^\s*commands:\s*\[(.*)\]\s*$/m.exec(frontmatter[1]);
  if (!line) return [];
  return line[1]
    .split(',')
    .map((entry) => entry.trim().replace(/^['"]|['"]$/g, ''))
    .filter(Boolean);
}

function renderQuickRef(skillName, commands) {
  const lines = [];
  lines.push(`# ${skillName} — commands quick reference (generated)`);
  lines.push('');
  lines.push(`Generated by \`scripts/gen-docs.mjs\` from the command schemas owned by this skill. Do not edit by hand; change the command schema and run \`npm run docs:build\`.`);
  lines.push('');
  for (const commandName of commands) {
    const spec = COMMANDS.find((cmd) => cmd.name === commandName);
    if (!spec) {
      lines.push(`## \`abap ${commandName}\``);
      lines.push('');
      lines.push('Subcommand; see the parent command reference (`abap ' + commandName.split(' ')[0] + ' --help`).');
      lines.push('');
      continue;
    }
    const schema = schemas.get(commandName);
    lines.push(`## \`abap ${commandName}\``);
    lines.push('');
    lines.push(esc(schema.description ?? spec.summary));
    lines.push('');
    if (schema.usage) {
      lines.push('```bash');
      lines.push(schema.usage);
      lines.push('```');
      lines.push('');
    }
    if (schema.options?.length) {
      const rows = schema.options
        .filter((opt) => opt.name !== '--schema')
        .map((opt) => [code(opt.valuePlaceholder ? `${opt.name} ${opt.valuePlaceholder}` : opt.name), esc(opt.description)]);
      lines.push(table(['Option', 'Description'], rows));
      lines.push('');
    }
    if (schema.examples?.length) {
      lines.push(renderExamples(schema.examples.slice(0, 2)));
      lines.push('');
    }
  }
  return lines.join('\n');
}

// ─── wiki/commands/index.md ─────────────────────────────────────────────────
function wikiPageFor(commandName) {
  return commandName.replace(/:/g, '-');
}

function renderWikiIndex() {
  const lines = [];
  lines.push('# Commands');
  lines.push('');
  lines.push('Per-command knowledge pages (prerequisites, gotchas, real-system evidence) live next to this index. The generated parameter reference is `docs/commands.md`; every command below must have a page.');
  lines.push('');
  lines.push(table(['Command', 'Page', 'Summary'], COMMANDS.map((cmd) => [code(`abap ${cmd.name}`), `[${wikiPageFor(cmd.name)}.md](${wikiPageFor(cmd.name)}.md)`, esc(cmd.summary)])));
  lines.push('');
  lines.push('Non-command contracts in this directory: [path-output.md](path-output.md).');
  lines.push('');
  return lines.join('\n');
}

// ─── wiki page stubs (hand-written pages are never overwritten) ────────────
function renderWikiPage(cmd) {
  const schema = schemas.get(cmd.name);
  const now = new Date();
  const stamp = `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, '0')}-${String(now.getUTCDate()).padStart(2, '0')} ${String(now.getUTCHours()).padStart(2, '0')}:${String(now.getUTCMinutes()).padStart(2, '0')}:${String(now.getUTCSeconds()).padStart(2, '0')}`;
  const lines = [];
  lines.push('---');
  lines.push('type: command');
  lines.push(`title: abap ${cmd.name}`);
  lines.push(`description: ${JSON.stringify(schema.description ?? cmd.summary)}`);
  lines.push(`tags: [command, ${cmd.name}]`);
  lines.push(`created at: ${stamp}`);
  lines.push(`changed at: ${stamp}`);
  lines.push('---');
  lines.push('');
  lines.push(`# \`abap ${cmd.name}\``);
  lines.push('');
  lines.push(esc(schema.description ?? cmd.summary));
  lines.push('');
  lines.push('## Usage');
  lines.push('');
  lines.push('```bash');
  lines.push(schema.usage ?? `abap ${cmd.name}`);
  lines.push('```');
  lines.push('');
  if (schema.arguments?.length) {
    lines.push('## Arguments');
    lines.push('');
    lines.push(renderArguments(schema.arguments));
    lines.push('');
  }
  lines.push('## Options');
  lines.push('');
  lines.push(renderOptions(schema.options) || '_No command-specific options._');
  lines.push('');
  lines.push('## Examples');
  lines.push('');
  lines.push(renderExamples(schema.examples) || '_See `docs/commands.md` for the generated reference._');
  lines.push('');
  lines.push('## Expected Output');
  lines.push('');
  lines.push('`--json` returns the standard envelope; success on stdout, errors on stderr with a categorized exit code. See [agent-integration](../../docs/agent-integration.md).');
  lines.push('');
  lines.push('# More');
  lines.push('');
  lines.push('_Add real-system observations (prerequisites, gotchas, evidence) here; this page is generated once as a stub and then owned by maintainers._');
  lines.push('');
  lines.push('# references');
  lines.push('');
  lines.push('- [docs/commands.md](../../docs/commands.md) — generated parameter reference');
  lines.push('- [agent-integration.md](../../docs/agent-integration.md) — `--json` contract');
  lines.push('');
  return lines.join('\n');
}

function isKnownCommandName(commandName) {
  if (COMMANDS.some((cmd) => cmd.name === commandName)) return true;
  // Subcommands (e.g. "create local") are allowed when the parent exists.
  const parent = commandName.split(' ')[0];
  return COMMANDS.some((cmd) => cmd.name === parent);
}

// ─── collect outputs & compare ──────────────────────────────────────────────
const outputs = new Map();
outputs.set('docs/commands.md', renderCommandsDoc());

const skillDirs = fs
  .readdirSync(path.join(repoRoot, 'skills'), { withFileTypes: true })
  .filter((entry) => entry.isDirectory() && fs.existsSync(path.join(repoRoot, 'skills', entry.name, 'SKILL.md')))
  .map((entry) => entry.name);

for (const skill of skillDirs) {
  const refsDir = path.join(repoRoot, 'skills', skill, 'references');
  if (!fs.existsSync(refsDir)) continue;
  const commands = parseSkillCommands(path.join(repoRoot, 'skills', skill, 'SKILL.md'));
  // Skills that only route to other skills (e.g. the performance methodology)
  // own no commands, so they get no generated quick reference.
  if (commands.length === 0) continue;
  outputs.set(`skills/${skill}/references/commands-quick.md`, renderQuickRef(skill, commands));
}

outputs.set('wiki/commands/index.md', renderWikiIndex());

// ─── apply / check ──────────────────────────────────────────────────────────
const problems = [];

for (const [relPath, content] of outputs) {
  const absPath = path.join(repoRoot, relPath);
  const current = fs.existsSync(absPath) ? fs.readFileSync(absPath, 'utf8') : undefined;
  if (MODE === 'write') {
    if (current !== content) {
      fs.mkdirSync(path.dirname(absPath), { recursive: true });
      fs.writeFileSync(absPath, content, 'utf8');
      console.log(`gen-docs: wrote ${relPath}`);
    }
  } else if (current !== content) {
    problems.push(`${relPath} is out of date`);
  }
}

// Every command needs a wiki page (narrative pages stay hand-written).
for (const cmd of COMMANDS) {
  const relPath = `wiki/commands/${wikiPageFor(cmd.name)}.md`;
  const absPath = path.join(repoRoot, relPath);
  if (fs.existsSync(absPath)) continue;
  if (MODE === 'write') {
    fs.mkdirSync(path.dirname(absPath), { recursive: true });
    fs.writeFileSync(absPath, renderWikiPage(cmd), 'utf8');
    console.log(`gen-docs: created wiki stub ${relPath}`);
  } else {
    problems.push(`missing wiki page for 'abap ${cmd.name}': ${relPath}`);
  }
}

// README command tables are hand-curated; docs:check only enforces coverage.
for (const readmeName of ['README.md', 'README.zh-CN.md']) {
  const readmeText = fs.readFileSync(path.join(repoRoot, readmeName), 'utf8');
  for (const cmd of COMMANDS) {
    if (!readmeText.includes(`abap ${cmd.name}`)) problems.push(`${readmeName} command table is missing 'abap ${cmd.name}'`);
  }
}

// Every command listed by a skill must exist.
for (const skill of skillDirs) {
  for (const commandName of parseSkillCommands(path.join(repoRoot, 'skills', skill, 'SKILL.md'))) {
    if (!isKnownCommandName(commandName)) {
      problems.push(`skills/${skill}/SKILL.md lists unknown command '${commandName}'`);
    }
  }
}

if (problems.length > 0) {
  for (const problem of problems) console.error(`gen-docs: ${problem}`);
  console.error(`gen-docs: ${MODE === 'check' ? 'documentation drift detected' : `${problems.length} problem(s)`}`);
  process.exit(1);
}

console.log(MODE === 'write' ? 'gen-docs: up to date' : 'gen-docs: no drift');
